.stage-option {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.8em;
  overflow: hidden;
  background: var(--c-lavender);
  color: var(--c-blue);
  border-radius: clamp(14px, 1.4vw, 24px);
